      SUBROUTINE ROTATC(NM)CC     ROTATES FLOOR COORDINATE TRANSFORMATION FOR ELEMENTCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM20.CIN'      INCLUDE 'OC.CIN'      INCLUDE 'OIV.CIN'C ----------------------------------------------------------------------      REAL           OS(3,3), OT(3,3), O1(3,3), XS(3), XT(3)C      CSR = COS(TOTROT)      IF (ABS(CSR) .LT. 0.00001) CSR = 0.0      SNR = SIN(TOTROT)      IF (ABS(SNR) .LT. 0.00001 .AND. ABS(TOTRA) .GT. 0.01) SNR = 0.0CC     IDENTIFY MATRIX TO BE ROTATEDC      IF (NM .EQ. 0) THEN        DO 10 J = 1, 3        DO 10 K = 1, 3   10   OS(J,K) = O(1,J,K)        DO 20 J = 1, 3   20   XS(J) = X0(1,J)      ELSE        DO 75 J = 1, 3        DO 75 K = 1, 3   75   OS(J,K) = OIV(J,K)        DO 80 J = 1, 3   80   XS(J) = XIV(J)      ENDIFCC     ROTATE AT ENTRANCEC      O1(1,1) = CSR      O1(1,2) = SNR      O1(2,1) = - SNR      O1(2,2) = CSR      DO 181 J = 1, 2      O1(J,3) = 0.0      O1(3,J) = 0.0  181 CONTINUE      O1(3,3) = 1.0C      DO 190 J = 1, 3      DO 190 K = 1, 3      SS = 0.0      DO 185 L = 1, 3      SS = SS + OS(J,L)*O1(L,K)  185 CONTINUE      OT(J,K) = SS  190 CONTINUECC     ROTATE AT EXITC      DO 260 J = 1, 3      DO 260 K = 1, 3      SS = 0.0      DO 255 L = 1, 3      SS = SS + O1(L,J)*OT(L,K)  255 CONTINUE      OS(J,K) = SS  260 CONTINUEC      DO 270 J = 1, 3      SS = 0.0      DO 265 L = 1, 3      SS = SS + O1(L,J)*XS(L)  265 CONTINUE      XT(J) = SS  270 CONTINUE      DO 275 J = 1, 3  275 XS(J) = XT(J)CC     REPLACE ROTATED MATRIXC  400 IF (NM .EQ. 0) THEN        DO 440 J = 1, 3        DO 440 K = 1, 3        O(1,J,K) = OS(J,K)  440   CONTINUE        DO 445 J = 1, 3  445   X0(1,J) = XS(J)      ELSE        DO 490 J = 1, 3        DO 490 K = 1, 3        OIV(J,K) = OS(J,K)  490   CONTINUE        DO 495 J = 1, 3  495   XIV(J) = XS(J)      ENDIFC  500 CONTINUE      RETURN      END